entries[73620] = { ["name"] = "Karneolspitzen", ["text"] = "Wirken in 3 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nKarneol (3), Juweliersfassung (3)\nOptionale Reagenzien:\n[] (#47)\nBerufsausbilder:\nJuwelierskunst des Kataklysmus (10)\nKosten:\n30\n\nKarneolspitzen\nWird beim Anlegen gebunden\nEinhändig Faustwaffe\n4 - 7 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 55 / 55\n30" }
entries[73621] = { ["name"] = "Der Perforator", ["text"] = "Wirken in 3 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nHeliodor , Dämonenauge , Traumsmaragd , Gluttopas , Ozeansaphir , Infernorubin\nOptionale Reagenzien:\n[] (#48)\nBerufsausbilder:\nJuwelierskunst des Kataklysmus (40)\nKosten:\n1\n50\n\nDer Perforator\nWird beim Anlegen gebunden\nEinhändig Faustwaffe\n4 - 7 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 1 Meisterschaft\n\nHaltbarkeit 65 / 65\n31" }
entries[73622] = { ["name"] = "Sternenstaub", ["text"] = "Wirken in 3.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nNachtstein\nBerufsausbilder:\nJuwelierskunst des Kataklysmus (1)\nKosten:\n10\n\nWird beim Aufheben gebunden\nBenutzen: Bestäubt ein befreundetes Ziel, um es zum Glitzern zu bringen! (10 Sek. Abklingzeit)" }
entries[73623] = { ["name"] = "Strassbesetzte Sonnenbrille", ["text"] = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nEchtgold (2), Schimärenauge (2), Hypnotischer Staub (8), Traumsmaragd (2)\nBeute von:\nWeltkreaturen\n\nStrassbesetzte Sonnenbrille\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
