entries[73685] = { ["name"] = "Leben entfesseln", ["text"] = "0.8% von Grundmana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\n1 Aufladung\nEntfesselt die Elementarkräfte des Lebens und heilt ein verbündetes Ziel um (319.2% der Zaubermacht) Gesundheit. Zusätzlich wird Euer nächster Heilzauber effektiver.\n\n'Springflut', 'Welle der Heilung' oder 'Heilende Woge' : Heilung um 35% erhöht.\n\n'Kettenheilung' : Heilung um 15% erhöht und springt auf 1 zusätzliches Ziel über.\n\n'Heilender Regen' oder 'Platzregen' : Wirkt sich auf 2 zusätzliche Ziele aus.\n\n'Lebensquell' : 40% der überschüssigen Heilung werden in einen Absorptionseffekt umgewandelt." }
